css:
:root { --text: #1a1a1a; --bg: #fff; }
body { font-size: 16px; color: var(--text); background: var(--bg); margin: 0; padding: 16px; }
h1 { font-size: 32px; margin: 0 0 8px; }
p { font-size: 16px; line-height: 1.6; margin: 0 0 16px; }
small { font-size: 14px; }
button:focus-visible { outline: 2px solid #005fcc; outline-offset: 2px; }
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
}
